import Modal from '../../common/components/RoleplayModal';
import Icon from 'flarum/common/components/Icon';
import { effectLabel, effectSource, effectIcon } from '../../common/character/effectPresentation';
/** Только объяснение готовых эффектов. Окно не меняет состояние и не считает бонусы повторно. */
export default class CharacterEffectsModal extends Modal {
  modalClassName() {
    return 'RpEffectsModal';
  }
  modalHeading() {
    return {
      label: 'Эффекты',
      purpose: 'effects'
    };
  }
  content() {
    const effects = this.attrs.effects;
    return m("div", {
      className: "Modal-body"
    }, !effects.length ? m("p", {
      className: "RpEffects-empty"
    }, "\u042D\u0444\u0444\u0435\u043A\u0442\u043E\u0432 \u043D\u0435\u0442.") : m("ul", {
      className: "RpEffects-list"
    }, effects.map((effect, index) => {
      return m("li", {
        key: index
      }, m("span", {
        className: "RpEffects-source",
        tabindex: 0,
        title: effectSource(effect),
        "aria-label": effectSource(effect)
      }, m(Icon, {
        name: effectIcon(effect, this.attrs.lookups)
      })), m("span", {
        className: "RpEffects-label"
      }, effectLabel(effect, this.attrs.lookups)));
    })));
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/CharacterEffectsModal', CharacterEffectsModal);