import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { damage, damageTiers } from '../../presentation';
import { uiIcon } from '../../uiIcons';
import { FieldLabel } from './FormFields';
/** Составные ступени удобны для ввода, но в форму уходит единственное числовое значение. */
export default class DamageEditor extends Component {
  parts = [];
  nextId = 1;
  oninit(vnode) {
    super.oninit(vnode);
    let left = this.attrs.state.number(this.attrs.field ?? 'damage_units');
    for (const tier of damageTiers) {
      const count = Math.floor(left / tier.value);
      left %= tier.value;
      if (count) this.parts.push({
        id: this.nextId++,
        tier: tier.value,
        count
      });
    }
  }
  sync() {
    this.attrs.state.set(this.attrs.field ?? 'damage_units', this.parts.reduce((sum, part) => sum + part.tier * part.count, 0));
  }
  view() {
    return m("section", {
      className: "RpDamageEditor RpField"
    }, m(FieldLabel, {
      label: this.attrs.label ?? 'Урон',
      icon: this.attrs.field === 'ignored_damage_units' ? 'combat.defense' : 'fields.damage'
    }), m("div", {
      className: "RpDamage-summary"
    }, damage(this.attrs.state.number(this.attrs.field ?? 'damage_units'))), m("div", null, this.parts.map(part => m("div", {
      key: part.id,
      className: "RpDamage-part"
    }, m("select", {
      className: "FormControl",
      "aria-label": this.attrs.label ? 'Ступень: ' + this.attrs.label : 'Ступень урона',
      value: part.tier,
      onchange: event => {
        part.tier = Number(event.target.value);
        this.sync();
      }
    }, damageTiers.map(tier => m("option", {
      key: tier.value,
      value: tier.value
    }, tier.name))), m("span", null, "\xD7"), m("input", {
      className: "FormControl",
      type: "number",
      "aria-label": "\u041A\u043E\u043B\u0438\u0447\u0435\u0441\u0442\u0432\u043E \u0441\u0442\u0443\u043F\u0435\u043D\u0435\u0439",
      required: true,
      min: 1,
      max: 1000000,
      value: part.count,
      oninput: event => {
        const value = event.target.value;
        part.count = value === '' ? NaN : Number(value);
        this.sync();
      }
    }), m(Button, {
      className: "Button Button--icon",
      icon: uiIcon('actions.close'),
      "aria-label": "\u0423\u0431\u0440\u0430\u0442\u044C \u0441\u0442\u0443\u043F\u0435\u043D\u044C",
      onclick: () => {
        this.parts = this.parts.filter(row => row.id !== part.id);
        this.sync();
      }
    })))), m(Button, {
      className: "Button Button--link RpDamage-add",
      icon: uiIcon('actions.create'),
      onclick: () => {
        this.parts.push({
          id: this.nextId++,
          tier: 3,
          count: 1
        });
        this.sync();
      }
    }, "\u0414\u043E\u0431\u0430\u0432\u0438\u0442\u044C \u0441\u0442\u0443\u043F\u0435\u043D\u044C"));
  }
}
flarum.reg.add('maxcuso-roleplay', 'common/catalog/components/DamageEditor', DamageEditor);