import Icon from 'flarum/common/components/Icon';
import { definition, nameColumn, referenceFilter, statusFilter } from './base';
import ItemEditor from '../../editors/ItemEditor';
import { number, object, text } from '../helpers';
import { damage, itemStackPrice } from '../../presentation';
import { uiIcon } from '../../uiIcons';
export default definition({
  key: 'items',
  title: 'Предметы',
  icon: 'sections.items',
  filters: [referenceFilter('type', 'Все типы', 'item-types'), {
    key: 'magical',
    label: 'Все предметы',
    options: () => ({
      '1': 'Только магические',
      '0': 'Немагические'
    })
  }, statusFilter],
  columns: [nameColumn('item'), {
    key: 'magical',
    title: 'Магический',
    render: row => m("input", {
      type: "checkbox",
      checked: Boolean(row.is_magical),
      disabled: true,
      "aria-label": "\u041C\u0430\u0433\u0438\u0447\u0435\u0441\u043A\u0438\u0439 \u043F\u0440\u0435\u0434\u043C\u0435\u0442"
    })
  }, {
    key: 'properties',
    title: 'Свойства',
    render: row => {
      const properties = Array.isArray(row.properties) ? row.properties : [];
      return m("span", {
        title: properties.map(value => text(object(value), 'description')).join('\n')
      }, properties.length || '—');
    }
  }, {
    key: 'damage',
    title: 'Урон',
    render: row => number(row, 'damage_units') ? damage(number(row, 'damage_units')) : '—'
  }, {
    key: 'price',
    title: 'Стоимость',
    render: row => m("span", {
      className: "RpGold"
    }, m(Icon, {
      name: uiIcon('resources.gold')
    }), " ", itemStackPrice(number(row, 'base_price')))
  }, {
    key: 'weight',
    title: 'Вес',
    render: row => m("span", null, m(Icon, {
      name: uiIcon('resources.weight')
    }), " ", number(row, 'weight'))
  }],
  defaults: {
    item_type_id: null,
    rarity: 'common',
    appearance: '',
    is_magical: false,
    is_melee_weapon: false,
    is_ranged_weapon: false,
    is_magic_weapon: false,
    is_armor: false,
    is_ingredient: false,
    is_literature: false,
    consumed_on_learning: false,
    literature_contents: [],
    damage_units: 0,
    ignored_damage_units: 0,
    melee_proficiency_id: null,
    ranged_proficiency_id: null,
    magic_proficiency_id: null,
    weight: 0,
    base_price: 0,
    max_stack: 1,
    properties: [],
    effects: []
  },
  editor: ItemEditor
});
flarum.reg.add('maxcuso-roleplay', 'common/catalog/definitions/Items', definition);