import Feedback from '../../common/components/Feedback';
import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import ProfileApi from './ProfileApi';
import ProfileState from './ProfileState';
import ProfilePanel from './ProfilePanel';
import CharacterHistoryModal from './CharacterHistoryModal';
import ReviewHistoryModal from './ReviewHistoryModal';
import showModal from '../../common/showModal';
import { requestMessage } from '../../common/requestError';
/** Перенесён сценарий старой вкладки. Загрузка и переключение вынесены в тестируемое состояние. */
export default class RoleplayProfilePage extends UserPage {
  profile = (() => new ProfileState(new ProfileApi(), () => m.redraw()))();
  userError = '';
  disposed = false;
  linkedEvent = '';
  selectionLink = '';
  oninit(vnode) {
    super.oninit(vnode);
    void this.loadUser(m.route.param('username')).catch(() => {
      this.userError = 'Не удалось открыть профиль пользователя. Попробуйте обновить страницу';
      m.redraw();
    });
  }
  show(user) {
    super.show(user);
    const requested = Number(m.route.param('character'));
    const preferred = Number.isSafeInteger(requested) && requested > 0 ? requested : null;
    this.selectionLink = String(m.route.param('character') ?? '') + '/' + String(m.route.param('event') ?? '');
    if (app.forum.attribute('roleplayCanView')) void this.profile.loadUser(Number(user.id()), preferred);
  }
  content() {
    if (!app.forum.attribute('roleplayCanView')) return m(Feedback, {
      message: "\u0423 \u0432\u0430\u0441 \u043D\u0435\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043A \u0440\u043E\u043B\u0435\u0432\u044B\u043C \u043F\u0435\u0440\u0441\u043E\u043D\u0430\u0436\u0430\u043C",
      inline: true
    });
    if (this.userError) return m(Feedback, {
      message: this.userError
    });
    return m(ProfilePanel, {
      state: this.profile,
      picker: true,
      own: app.session.user?.id() === this.user?.id()
    });
  }
  onupdate() {
    const character = String(m.route.param('character') ?? ''),
      event = String(m.route.param('event') ?? '');
    // Переход из колокольчика может остаться внутри уже открытого профиля.
    if (this.user && character + '/' + event !== this.selectionLink) {
      this.selectionLink = character + '/' + event;
      this.linkedEvent = '';
      const id = Number(character);
      void this.profile.loadUser(Number(this.user.id()), Number.isSafeInteger(id) && id > 0 ? id : null);
      return;
    }
    const key = character + '/' + event;
    if (!/^\d+$/.test(event) || !/^\d+$/.test(character) || this.linkedEvent === key || !this.profile.view || this.profile.detailLoading || this.profile.selected !== Number(character)) return;
    this.linkedEvent = key;
    void app.request({
      method: 'GET',
      url: app.forum.attribute('apiUrl') + '/roleplay/characters/' + character + '/events/' + event,
      errorHandler: () => {}
    }).then(response => {
      if (this.disposed || this.profile.selected !== Number(character) || String(m.route.param('event') ?? '') !== event || String(m.route.param('character') ?? '') !== character) return;
      if (response.data.type === 'review_decided') showModal(ReviewHistoryModal, {
        events: [response.data]
      });else showModal(CharacterHistoryModal, {
        events: [response.data],
        lookups: this.profile.view?.lookups
      });
    }).catch(error => {
      if (!this.disposed && this.profile.selected === Number(character)) {
        app.alerts.show({
          type: 'error'
        }, requestMessage(error, 'Запись истории недоступна'));
      }
    });
  }
  onremove(vnode) {
    this.disposed = true;
    this.profile.dispose();
    super.onremove(vnode);
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/RoleplayProfilePage', RoleplayProfilePage);