import app from 'flarum/forum/app';
/** Только транспорт. Ошибки показывает мастер рядом с действием, без второй общей всплывающей ошибки. */
export default class CreationApi {
  url() {
    return app.forum.attribute('apiUrl') + '/roleplay/creation';
  }
  async read() {
    const response = await app.request({
      method: 'GET',
      url: this.url() + '/draft',
      errorHandler: () => {}
    });
    return response.data;
  }
  async save(body) {
    const response = await app.request({
      method: 'PUT',
      url: this.url() + '/draft',
      body,
      errorHandler: () => {}
    });
    return response.data;
  }
  async create(body) {
    const response = await app.request({
      method: 'POST',
      url: this.url(),
      body,
      errorHandler: () => {}
    });
    return response.data;
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/creation/CreationApi', CreationApi);