import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import { object, text } from '../../common/catalogData';
import RankLabel from '../../common/character/RankLabel';
import { uiIcon } from '../../common/uiIcons';
import { historyDate, historyDays, historyHeading, historyResources } from './historyPresentation';
/** Только отображение разрешённого сервером журнала. Начисления и причины не загружаем отдельно. */
export default class CharacterHistory extends Component {
  view() {
    if (!this.attrs.events.length) return m("p", {
      className: "RpCharacterHistory-empty"
    }, "\u0418\u0441\u0442\u043E\u0440\u0438\u044F \u043F\u043E\u043A\u0430 \u043F\u0443\u0441\u0442\u0430.");
    return m("div", {
      className: "RpCharacterHistory"
    }, historyDays(this.attrs.events).map(day => m("section", {
      className: "RpCharacterHistory-day",
      key: day.key,
      "aria-label": day.label
    }, m("h3", null, day.label, day.date && m("span", null, day.date)), m("ul", null, day.events.map(event => this.event(event))))));
  }
  event(event) {
    const details = event.details;
    const heading = historyHeading(event, this.attrs.lookups ?? {});
    const resources = historyResources(details);
    const beforeRank = object(details.before),
      afterRank = object(details.after);
    const date = historyDate(event.created_at);
    const exactTime = date?.toLocaleString('ru-RU', {
      day: 'numeric',
      month: 'long',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }) ?? event.created_at;
    return m("li", {
      key: event.id
    }, m("span", {
      className: "RpCharacterHistory-icon",
      "aria-hidden": "true"
    }, m(Icon, {
      name: heading.icon
    })), m("div", {
      className: "RpCharacterHistory-content"
    }, m("div", {
      className: "RpCharacterHistory-heading"
    }, m("strong", null, heading.label), m("time", {
      datetime: date?.toISOString(),
      title: exactTime
    }, date?.toLocaleTimeString('ru-RU', {
      hour: '2-digit',
      minute: '2-digit'
    }) ?? '—')), heading.caption && m("div", {
      className: "RpCharacterHistory-caption"
    }, heading.caption), resources.length > 0 && m("div", {
      className: "RpCharacterHistory-resources"
    }, resources.map(resource => m("span", {
      key: resource.kind,
      className: 'RpCharacterHistory-resource is-' + resource.kind + (resource.value > 0 ? ' is-positive' : '')
    }, m(Icon, {
      name: uiIcon(resource.kind === 'gold' ? 'resources.gold' : 'resources.activeExperience')
    }), resource.label))), details.action === 'set_rank' && m("div", {
      className: "RpCharacterHistory-caption"
    }, beforeRank.name ? m(RankLabel, {
      rank: beforeRank
    }) : 'Без ранга', " \u2192 ", afterRank.name ? m(RankLabel, {
      rank: afterRank
    }) : 'Без ранга'), (details.action === 'episode_reward' || details.action === 'topic_reward') && Array.isArray(details.grants) && details.grants.map((grant, index) => {
      const row = object(grant);
      return m("div", {
        className: "RpCharacterHistory-caption",
        key: index
      }, text(row, 'name'), Number(row.quantity) > 1 ? ' × ' + Number(row.quantity) : '');
    }), text(details, 'comment') && m("p", {
      className: "RpCharacterHistory-comment"
    }, text(details, 'comment'))));
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/CharacterHistory', CharacterHistory);