import app from 'flarum/forum/app';
/** Транспорт редактора повторно использует CreationState.
 * save только проверяет форму; PUT при create атомарно меняет существующую анкету.
 * revision формы и revision персонажа независимы: просмотр шагов не меняет персонажа.
 */
export default class MechanicsEditApi {
  view = null;
  constructor(id) {
    this.id = id;
  }
  url() {
    return app.forum.attribute('apiUrl') + '/roleplay/characters/' + this.id + '/mechanics';
  }
  async read() {
    const result = await app.request({
      method: 'GET',
      url: this.url(),
      errorHandler: () => {}
    });
    this.view = result.data;
    return this.view;
  }
  async save(body) {
    const result = await app.request({
      method: 'POST',
      url: this.url(),
      body: {
        ...body,
        character_revision: this.view.character_revision
      },
      errorHandler: () => {}
    });
    this.view = result.data;
    return this.view;
  }
  async create(command) {
    const view = this.view;
    const result = await app.request({
      method: 'PUT',
      url: this.url(),
      body: {
        operation_key: command.operation_key,
        revision: view.character_revision,
        catalog_revision: command.catalog_revision,
        rules_hash: command.rules_hash,
        payload: view.draft.payload
      },
      errorHandler: () => {}
    });
    return result.data;
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/MechanicsEditApi', MechanicsEditApi);