import app from 'flarum/forum/app';
class CompletionSelectionApi {
  constructor(base, kind) {
    this.base = base;
    this.kind = kind;
  }
  async list(params) {
    return (await app.request({
      method: 'GET',
      url: this.base + '/catalogs/' + this.kind,
      params,
      errorHandler: () => {}
    })).data;
  }
  async save(_id, _revision, _fields) {
    throw new Error('В этом окне доступен только выбор награды');
  }
  async toggle() {
    throw new Error('В этом окне доступен только выбор награды');
  }
  async remove() {
    throw new Error('В этом окне доступен только выбор награды');
  }
}

/** Подготовка BB-кода не выполняет команды персонажа или закрытия темы. */
export default class EpisodeCompletionApi {
  prepared = null;
  constructor(discussionId) {
    this.base = app.forum.attribute('apiUrl') + '/roleplay/episodes/' + discussionId + '/completion';
    this.characters = new CompletionSelectionApi(this.base, 'characters');
  }
  async context() {
    return (await app.request({
      method: 'GET',
      url: this.base,
      errorHandler: () => {}
    })).data;
  }
  catalog(kind) {
    return new CompletionSelectionApi(this.base, kind);
  }
  async character(id) {
    return (await app.request({
      method: 'GET',
      url: this.base + '/characters/' + id,
      errorHandler: () => {}
    })).data;
  }
  async prepare(payload) {
    const json = JSON.stringify(payload);
    // Потеря ответа не создаёт новое намерение с теми же настройками.
    if (!this.prepared || this.prepared.json !== json) this.prepared = {
      json,
      key: crypto.randomUUID()
    };
    return (await app.request({
      method: 'POST',
      url: this.base,
      body: {
        operation_key: this.prepared.key,
        payload
      },
      errorHandler: () => {}
    })).data.code;
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/episodes/EpisodeCompletionApi', EpisodeCompletionApi);