import app from 'flarum/forum/app';
import UserPage from 'flarum/forum/components/UserPage';
import Button from 'flarum/common/components/Button';
import Feedback from '../../common/components/Feedback';
import WorkspaceCatalog from './WorkspaceCatalog';
import WorkspaceEpisodes from './WorkspaceEpisodes';
/** Личное рабочее пространство аккаунта: не загружает и не выбирает персонажа. */
export default class WorkspacePage extends UserPage {
  selected = 'episodes';
  error = '';
  oninit(vnode) {
    super.oninit(vnode);
    void this.loadUser(m.route.param('username')).catch(() => {
      this.error = 'Не удалось открыть профиль. Попробуйте обновить страницу';
      m.redraw();
    });
  }
  content() {
    if (this.error) return m(Feedback, {
      message: this.error
    });
    if (!this.user) return null;
    if (!app.forum.attribute('roleplayCanUseWorkspace') || app.session.user?.id() !== this.user.id()) {
      return m(Feedback, {
        message: "\u0423 \u0432\u0430\u0441 \u043D\u0435\u0442 \u0434\u043E\u0441\u0442\u0443\u043F\u0430 \u043A \u044D\u0442\u043E\u0439 \u043C\u043E\u0434\u0435\u0440\u0430\u0442\u043E\u0440\u0441\u043A\u043E\u0439",
        inline: true
      });
    }
    const tabs = [{
      key: 'episodes',
      title: 'Мои эпизоды',
      icon: 'fas fa-calendar-alt'
    }];
    if (app.forum.attribute('roleplayWorkspaceCatalogs')) tabs.push({
      key: 'perks',
      title: 'Перки',
      icon: 'fas fa-star'
    }, {
      key: 'spells',
      title: 'Заклинания',
      icon: 'fas fa-book'
    }, {
      key: 'items',
      title: 'Предметы',
      icon: 'fas fa-toolbox'
    });
    return m("div", {
      className: "RpWorkspace"
    }, m("nav", {
      key: "navigation",
      className: "RpWorkspace-tabs",
      "aria-label": "\u0420\u0430\u0437\u0434\u0435\u043B\u044B \u043C\u043E\u0434\u0435\u0440\u0430\u0442\u043E\u0440\u0441\u043A\u043E\u0439"
    }, tabs.map(tab => m(Button, {
      key: tab.key,
      className: 'Button ' + (this.selected === tab.key ? 'Button--primary' : ''),
      icon: tab.icon,
      "aria-pressed": String(this.selected === tab.key),
      onclick: () => {
        this.selected = tab.key;
      }
    }, tab.title))), this.selected === 'episodes' ? m(WorkspaceEpisodes, {
      key: "episodes"
    }) : m(WorkspaceCatalog, {
      key: this.selected,
      catalog: this.selected
    }));
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/workspace/WorkspacePage', WorkspacePage);