export const reviewParts = {
  mechanics: 'Техническая часть',
  literature: 'Литературная часть'
};
const statuses = {
  draft: {
    label: 'Ожидает отправки',
    icon: 'review.waiting'
  },
  review: {
    label: 'На проверке',
    icon: 'review.waiting'
  },
  changes_requested: {
    label: 'Требуются исправления',
    icon: 'actions.edit'
  },
  approved: {
    label: 'Одобрена',
    icon: 'actions.select'
  }
};

/** Подписи одинаковы в панели и истории; черновик литературной части ещё заполняется. */
export function reviewStatus(part, status) {
  return part === 'literature' && status === 'draft' ? {
    label: 'В работе',
    icon: 'actions.edit'
  } : statuses[status] ?? {
    label: status,
    icon: 'review.waiting'
  };
}
flarum.reg.add('maxcuso-roleplay', 'forum/profile/reviewPresentation', { reviewParts: reviewParts,reviewStatus: reviewStatus, });