import Modal from '../../../common/components/RoleplayModal';
import EventForm from './EventForm';
/** Форма находится вне прокручиваемой панели редактора и не обрезается ею. */
export default class EventCreateModal extends Modal {
  modalClassName() {
    return 'Modal--large QuestEventCreateModal';
  }
  modalHeading() {
    return {
      label: 'Создание события',
      purpose: 'create'
    };
  }
  content() {
    return m(EventForm, {
      oninsert: this.attrs.oninsert,
      oncancel: () => this.hide()
    });
  }
}
flarum.reg.add('maxcuso-roleplay', 'forum/events/components/EventCreateModal', EventCreateModal);